def parse_duration(value):
    if not value or not value.strip():
        raise ValueError("Input string is empty")

    parts = value.split()
    if not parts:
        raise ValueError("No valid terms found")

    total_seconds = 0
    unit_map = {
        'h': 3600,
        'm': 60,
        's': 1
    }

    for part in parts:
        # Find the split point between digits and unit
        # The unit must be the last character
        if len(part) < 2:
            raise ValueError(f"Invalid term: {part}")

        unit = part[-1].lower()
        if unit not in unit_map:
            raise ValueError(f"Unknown unit: {unit}")

        quantity_str = part[:-1]
        try:
            quantity = int(quantity_str)
        except ValueError:
            raise ValueError(f"Non-integer quantity: {quantity_str}")

        total_seconds += quantity * unit_map[unit]

    return total_seconds

