def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate intervals and sort by start time
    sorted_intervals = []
    for start, end in intervals:
        if start > end:
            raise ValueError("Start of interval cannot be greater than end.")
        sorted_intervals.append((start, end))

    sorted_intervals.sort()

    merged = []
    for current_start, current_end in sorted_intervals:
        if not merged:
            merged.append([current_start, current_end])
        else:
            prev_start, prev_end = merged[-1]
            # If current interval overlaps or touches the previous one
            if current_start <= prev_end:
                # Update the end of the last interval in the list
                merged[-1][1] = max(prev_end, current_end)
            else:
                # No overlap, add the current interval as a new entry
                merged.append([current_start, current_end])

    return [tuple(interval) for interval in merged]

